head.script:
// 원본 : ULDSTF07404 (팝업)전문평가 메일발송 (/ui/sample/template/ULDSTF07404.xml)
// 원본의 화면 구성과 흐름을 그대로 두고 전문평가 업무 문구만 예시로 바꾼 가이드다.

/*
 * 화면 동작
 * 1. 팝업 로딩시 발신자 기본값을 설정하고 메일 기본정보를 조회
 * 2. 「대상」 선택시 대상에 맞는 메일제목과 발신내용을 자동으로 채움
 * 3. 「받는곳 찾기」 클릭시 담당자 찾기 팝업 호출, 「행삽입」 으로 직접 입력도 가능
 * 4. 「파일추가」 클릭시 첨부파일 선택, 파일명 더블클릭시 다운로드
 * 5. 「발송」 클릭시 수신자·제목·내용 검증 후 첨부파일과 함께 전송하고, 부모 화면을 다시 조회한 뒤 닫음
 *
 * 담긴 패턴
 * - 부모가 넘긴 파라미터 수신, 부모 화면 함수 호출 ($c.win.getParent)
 * - 대상 선택에 따라 제목·본문 템플릿 교체
 * - 수신자 : 팝업으로 찾아 추가 / 직접입력 / 행추가·삭제 / 전체선택 토글
 * - 첨부파일 : 개수 제한, 전체 용량 제한, 목록 표시, 다운로드
 * - 이메일 형식 검증 ($c.str.isEmail)
 * - multiupload 로 입력값과 파일을 한 번에 전송
 * - 전송 완료 후 부모 재조회하고 닫기
 *
 * 복사해서 쓰는 순서
 * 1. 파일명과 meta_screenId 를 실제 화면ID 로 변경
 * 2. 메일 템플릿 함수를 업무 문구로 교체
 * 3. 발신자 기본값을 업무 발신자로 교체
 * 4. 수신자 찾기 팝업 경로를 실제 수신자 찾기 팝업으로 교체
 * 5. 각 통신의 action 경로를 실 API 로 교체
 * 6. 대상 구분이 없는 화면이면 rd_target 과 changeTarget 계열을 통째로 삭제
 */


///////// 1. 변수 및 선언 영역 /////////

scwin.screenId = "ULDSTF07404";

// 화면 상태값
scwin.notiSvcId = "";		// 알림서비스ID
scwin.parentWin = null;		// 부모 화면 scope
scwin.isAllChecked = false;	// 전체선택 토글 상태


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 08. 18
 * @description 페이지로드
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
	try {
		// 초기화 함수
		await scwin.init();
	} catch (ex) {
		await $c.exception.handleError(ex, { context : "ULDSTF07404.onpageload" });
	}
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 08. 18
 * @description 초기화. 부모 화면 scope 와 팝업 파라미터를 확보하고 메일 기본정보를 조회한다.
 *
 * 그리드 조작은 조회보다 뒤에 둔다. 조회 앞에 두면 조회가 통째로 막힐 수 있다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 받는 파라미터 이름
 * @param
 * @returns
 * @hidden N
*/
scwin.init = async function () {
	// 부모 화면 scope. 회사명·배정정보를 부모에서 가져올 때 쓴다.
	scwin.parentWin = $c.win.getParent();

	// openPopup 의 3번째 인자로 넘어온 값
	const param = $c.data.getParameter();

	scwin.notiSvcId = param?.notiSvcId ?? "";
	scwin.notiSvcId = "16"; // test 값 설정

	// 발신자 / 비밀참조 기본값 설정
	scwin.setSenderInfo();

	// 메일 기본정보 조회
	await scwin.selectMailInfo();
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.rd_target_onviewchange
 * @author Inswave
 * @date 2026. 08. 18
 * @description 대상 선택 변경. 대상에 맞는 메일제목과 발신내용을 설정한다.
 * @param
 * @returns
 * @hidden N
*/
scwin.rd_target_onviewchange = function (info) {
	try {
		scwin.changeTarget();
	} catch (ex) {
		$c.exception.handleError(ex, { context : "ULDSTF07404.rd_target_onviewchange" });
	}
};

/**
 * @event
 * @name scwin.btn_findReceiver_onclick
 * @author Inswave
 * @date 2026. 08. 18
 * @description 받는곳 찾기 버튼 클릭. 팝업에서 고른 담당자를 수신자 목록에 추가한다.
 *
 * 값을 돌려주는 선택 팝업이라 결과가 비었는지로 취소를 판단한다.
 * 팝업 안에서 처리를 끝내는 처리 팝업은 ULDFIL59411 를 본다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - openPopup 의 팝업 경로, 팝업 크기, 넘길 파라미터
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_findReceiver_onclick = async function (e) {
	try {
		const param = {
			parScrenId : scwin.screenId
		};

		const options = {
			id : "ULDFIL52110",
			popupName : "담당자 찾기",
			width : 1000,
			height : 600,
			frameModal : "top"
		};

		const result = await $c.win.openPopup("/ui/sample/template/ULDFIL52110.xml", options, param);

		// 선택 없이 닫으면 결과가 없다.
		if ($c.util.isEmpty(result)) return;

		// 찾기 팝업은 한 건을 돌려준다.
		// 여러 건을 받는 팝업이면 배열이 오므로 아래처럼 두 경우를 함께 받는다.
		const receivers = $c.util.isArray(result) ? result : [result];

		receivers.forEach(receiver => {
			scwin.addReceiver(receiver.chrgNm, receiver.email);
		});
	} catch (ex) {
		await $c.exception.handleError(ex, { context : "ULDSTF07404.btn_findReceiver_onclick" });
	}
};

/**
 * @event
 * @name scwin.btn_selectAll_onclick
 * @author Inswave
 * @date 2026. 08. 18
 * @description 전체선택/전체해제 토글 버튼 클릭
 *
 * 버튼 하나로 두 동작을 하므로 라벨도 함께 바꿔야 지금 상태를 알 수 있다.
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_selectAll_onclick = function (e) {
	try {
		scwin.isAllChecked = !scwin.isAllChecked;

		// 그리드 checkbox inputType 은 "1"/"0" 을 쓴다.
		const checkValue = scwin.isAllChecked ? "1" : "0";
		const rowCount = dlt_receiver.getRowCount();

		for (let i = 0; i < rowCount; i++) {
			dlt_receiver.setCellData(i, "check", checkValue);
		}

		btn_selectAll.setValue(scwin.isAllChecked ? "전체해제" : "전체선택");
	} catch (ex) {
		$c.exception.handleError(ex, { context : "ULDSTF07404.btn_selectAll_onclick" });
	}
};

/**
 * @event
 * @name scwin.btn_rowAdd_onclick
 * @author Inswave
 * @date 2026. 08. 18
 * @description 행삽입 버튼 클릭. 담당자를 직접 입력할 빈 행을 추가한다.
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_rowAdd_onclick = function (e) {
	try {
		dlt_receiver.insertRow();
	} catch (ex) {
		$c.exception.handleError(ex, { context : "ULDSTF07404.btn_rowAdd_onclick" });
	}
};

/**
 * @event
 * @name scwin.btn_rowDelete_onclick
 * @author Inswave
 * @date 2026. 08. 18
 * @description 행삭제 버튼 클릭. 체크한 담당자 행을 삭제한다.
 *
 * 뒤에서부터 지우지 않으면 앞 행을 지운 순간 뒤 인덱스가 하나씩 당겨져
 * 엉뚱한 행이 지워진다. 이 순서는 바꾸지 말 것.
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_rowDelete_onclick = function (e) {
	try {
		const checkedRows = grd_receiver.getCheckedIndex("check");

		if ($c.util.isEmpty(checkedRows)) {
			$c.win.alert($c.data.getMessage("com_crud_0199", "삭제할 담당자"));
			return;
		}

		for (let i = checkedRows.length - 1; i >= 0; i--) {
			dlt_receiver.removeRow(checkedRows[i]);
		}
	} catch (ex) {
		$c.exception.handleError(ex, { context : "ULDSTF07404.btn_rowDelete_onclick" });
	}
};

/**
 * @event
 * @name scwin.btn_fileAdd_onclick
 * @author Inswave
 * @date 2026. 08. 18
 * @description 파일추가 버튼 클릭. 최대 개수를 확인한 뒤 파일 선택창을 연다.
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_fileAdd_onclick = function (e) {
	try {
		if (dlt_fileList.getRowCount() >= 5) {
			// "com_file_0023": "첨부파일은 $[0]개까지 가능합니다."
			$c.win.alert($c.data.getMessage("com_file_0023", [5]));
			return;
		}

		// 공통함수가 multiupload 내부 input 을 클릭해 파일 대화상자를 연다.
		$c.util.onUploadClick(mpd_attachFile);
	} catch (ex) {
		$c.exception.handleError(ex, { context : "ULDSTF07404.btn_fileAdd_onclick" });
	}
};

/**
 * @event
 * @name scwin.btn_fileDelete_onclick
 * @author Inswave
 * @date 2026. 08. 18
 * @description 파일삭제 버튼 클릭. 그리드에서 선택한 첨부파일을 삭제한다.
 *
 * 아직 업로드 전인 파일은 multiupload 쪽에서도 빼야 전송 대상에서 빠진다.
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_fileDelete_onclick = function (e) {
	try {
		const rowIndex = dlt_fileList.getRowPosition();

		if (rowIndex < 0) {
			$c.win.alert($c.data.getMessage("com_crud_0199", "삭제할 첨부파일"));
			return;
		}

		const fileName = dlt_fileList.getCellData(rowIndex, "fileName");

		if (!$c.util.isEmpty(fileName)) {
			mpd_attachFile.removeFile(fileName);
		}

		dlt_fileList.removeRow(rowIndex);
	} catch (ex) {
		$c.exception.handleError(ex, { context : "ULDSTF07404.btn_fileDelete_onclick" });
	}
};

/**
 * @event
 * @name scwin.grd_fileList_oncelldblclick
 * @author Inswave
 * @date 2026. 08. 18
 * @description 첨부파일 파일명 더블클릭. 서버에 저장된 파일을 내려받는다.
 *
 * 방금 추가한 행은 아직 서버에 없어 내려받을 수 없다.
 * 행 상태가 "R"(조회된 행)일 때만 다운로드한다.
 *
 * $c.data.downFile 은 async 라 실패 시 reject 한다.
 * catch 를 붙이지 않으면 서버가 죽어 있어도 화면에 아무 반응이 없다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 내려받기 경로, 파라미터
 * @param
 * @returns
 * @hidden N
*/
scwin.grd_fileList_oncelldblclick = async function (rowIndex, columnIndex, columnId) {
	try {
		if (dlt_fileList.getRowStatus(rowIndex) !== "R") return;

		const fileName = dlt_fileList.getCellData(rowIndex, "fileName");

		const param = {
			notiSvcId : dlt_fileList.getCellData(rowIndex, "notiSvcId"),
			seq : dlt_fileList.getCellData(rowIndex, "fileSeq")
		};

		// "com_file_0106": "파일을 다운로드 할 수 없습니다."
		await $c.data.downFile("/api/listing/lstproc/ksqexpeval-mail/file-download", fileName, param)
			.catch(() => { $c.win.alert($c.data.getMessage("com_file_0106")); });
	} catch (ex) {
		await $c.exception.handleError(ex, { context : "ULDSTF07404.grd_fileList_oncelldblclick" });
	}
};

/**
 * @event
 * @name scwin.btn_send_onclick
 * @author Inswave
 * @date 2026. 08. 18
 * @description 전송 버튼 클릭
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_send_onclick = async function (e) {
	try {
		await scwin.sendMail();
	} catch (ex) {
		await $c.exception.handleError(ex, { context : "ULDSTF07404.btn_send_onclick" });
	}
};

/**
 * @event
 * @name scwin.btn_cancel_onclick
 * @author Inswave
 * @date 2026. 08. 18
 * @description 취소 버튼 클릭. 작성한 내용을 초기 상태로 되돌린다.
 *
 * 취소는 닫기가 아니다. 처음 열었을 때 상태로 되돌리고 팝업은 그대로 둔다.
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_cancel_onclick = async function (e) {
	try {
		dlt_fileList.removeAll();

		scwin.setSenderInfo();

		await scwin.selectMailInfo();
	} catch (ex) {
		await $c.exception.handleError(ex, { context : "ULDSTF07404.btn_cancel_onclick" });
	}
};

/**
 * @event
 * @name scwin.btn_close_onclick
 * @author Inswave
 * @date 2026. 08. 18
 * @description 닫기 버튼 클릭. 팝업을 닫는다.
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_close_onclick = function (e) {
	try {
		$c.win.closePopup();
	} catch (ex) {
		$c.exception.handleError(ex, { context : "ULDSTF07404.btn_close_onclick" });
	}
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.selectMailInfo
 * @author Inswave
 * @date 2026. 08. 18
 * @description 메일 기본정보(본문·첨부파일·담당자)를 조회한다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - action 경로, 요청 파라미터
 * @param
 * @returns
 * @hidden N
*/
scwin.selectMailInfo = async function () {
	const sbmOptions = {
		id : "sbm_selectMailInfo",
		method : "get",
		action : "/api/listing/lstproc/ksqexpeval-mail/init",
		target : "dma_master=body.mailInfo,dlt_fileList=body.attchFileList,dlt_receiver=body.sendReceiverList",
		isProcessMsg : false
	};

	const requestData = {
		notiSvcId : scwin.notiSvcId
	};

	// 통신 오류는 공통 오류 핸들러가 안내하고 예외를 던진다.
	// 여기서 잡지 않으므로 오류가 나면 아래 처리는 실행되지 않는다.
	const result = await $c.sbm.executeDynamic(sbmOptions, requestData);

	// 대상 선택을 비운다. 다시 고르면 제목·본문이 다시 채워진다.
	rd_target.setValue("");

	// 전체선택 상태도 함께 초기화한다.
	scwin.isAllChecked = false;
	btn_selectAll.setValue("전체선택");
};

/**
 * @method
 * @name scwin.sendMail
 * @author Inswave
 * @date 2026. 08. 18
 * @description 입력값을 검증한 뒤 첨부파일과 함께 메일을 전송한다.
 *
 * 입력값과 파일을 한 번에 보내야 하므로 일반 통신이 아니라 multiupload 로 보낸다.
 * setParam 으로 실은 값이 전문의 본문이 되고, 파일은 multipart 로 함께 간다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - action 경로, 전문 이름과 구조
 * @param
 * @returns
 * @hidden N
*/
scwin.sendMail = async function () {
	if (!await scwin.validate()) return;

	if (!scwin.checkFileSize()) return;

	// 되돌릴 수 없는 처리는 확인을 받는다.
	if (!await $c.win.confirm($c.data.getMessage("com_crud_0198", "전송"))) return;

	const requestDto = {
		master : dma_master.getJSON(),
		receiver : dlt_receiver.getAllJSON(),
		fileCnt : dlt_fileList.getRowCount()
	};

	mpd_attachFile.changeAction("/api/listing/lstproc/ksqexpeval-mail/send");
	mpd_attachFile.setParam(0, "ksqExpEvalSendMailRequestDto", JSON.stringify(requestDto));
	mpd_attachFile.startUpload();
};

/**
 * @event
 * @name scwin.mpd_attachFile_selectCallback
 * @author Inswave
 * @date 2026. 08. 18
 * @description 파일 선택 시 마지막으로 추가된 파일을 첨부파일 목록에 담는다.
 *
 * multiupload 는 고른 파일을 자기 안에 쌓아 둔다.
 * 화면에 보여줄 목록은 별도 DataList 라 여기서 옮겨 담는다.
 * @param
 * @returns
 * @hidden N
*/
scwin.mpd_attachFile_selectCallback = function (fileInfoArr) {
	const fileInfos = mpd_attachFile.getFileInfos();

	if ($c.util.isEmpty(fileInfos)) return;

	// 방금 추가된 파일은 항상 목록의 마지막이다.
	const fileInfo = fileInfos[fileInfos.length - 1];
	const rowIndex = dlt_fileList.insertRow(dlt_fileList.getRowCount());

	dlt_fileList.setCellData(rowIndex, "fileName", fileInfo.name);
	dlt_fileList.setCellData(rowIndex, "fileSize", $c.num.formatNumber(fileInfo.size));
	dlt_fileList.setCellData(rowIndex, "attachFileSz", fileInfo.size);
};

/**
 * @event
 * @name scwin.mpd_attachFile_onComplete
 * @author Inswave
 * @date 2026. 08. 18
 * @description 전송 완료. 부모 화면을 재조회하고 팝업을 닫는다.
 *
 * 부모에 재조회 함수가 있는지 확인하고 부른다.
 * 팝업이 어디서 열릴지 모르므로 없을 수도 있다고 보고 짠다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 부모 재조회 함수 이름
 * @param
 * @returns
 * @hidden N
*/
scwin.mpd_attachFile_onComplete = function () {
	$c.win.alert($c.data.getMessage("com_complete_0150", "전송"), () => {
		if (typeof scwin.parentWin?.scwin?.searchList === "function") {
			scwin.parentWin.scwin.searchList();
		}

		$c.win.closePopup();
	});
};

/**
 * @event
 * @name scwin.mpd_attachFile_onerror
