 * @date 2026. 08. 18
 * @description 전송 실패
 * @param
 * @returns
 * @hidden N
*/
scwin.mpd_attachFile_onerror = function (data) {
	$c.win.alert($c.data.getMessage("com_complete_0151", "전송"));
};


