/**
 * @method
 * @name scwin.setSenderInfo
 * @author Inswave
 * @date 2026. 08. 18
 * @description 보낸이 / 비밀참조 수신을 기본값으로 설정한다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 보낸이·비밀참조의 이름과 메일주소
 * @param
 * @returns
 * @hidden N
*/
