/**
 * @method
 * @name scwin.changeTarget
 * @author Inswave
 * @date 2026. 08. 18
 * @description 선택한 대상에 맞는 메일제목과 발신내용을 설정한다.
 *
 * 대상마다 제목·본문·수신자 처리가 다르다.
 * 본문은 길어지므로 대상별 함수로 빼고 여기서는 무엇을 부를지만 정한다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 대상 구분과 제목·본문
 * @param
 * @returns
 * @hidden N
*/
scwin.changeTarget = function () {
	const target = rd_target.getValue();
	const comNm = scwin.getParentComNm();

	if (target === "1") {
		dma_master.set("title", "(한국거래소) (" + comNm + ") 전문평가 신청 관련");
		dma_master.set("contn", scwin.getLeadComContent());

		// 주관사는 부모 화면의 접수담당자를 수신자로 채운다.
		scwin.setLeadComReceiver();
		return;
	}

	if (target === "2" || target === "3") {
		dma_master.set("title", "(한국거래소) (" + comNm + ") 전문평가 가능여부 회신 요청");
		dma_master.set("contn", scwin.getReplyRequestContent(comNm, target === "2"));

		dlt_receiver.removeAll();
		return;
	}

	if (target === "4") {
		dma_master.set("title", "(한국거래소) (" + comNm + ") 전문평가 배정의 건");
		dma_master.set("contn", scwin.getAllocationContent(comNm));

		dlt_receiver.removeAll();
	}
};

/**
 * @method
 * @name scwin.getLeadComContent
 * @author Inswave
 * @date 2026. 08. 18
 * @description 주관사 대상 발신내용을 반환한다.
 *
 * 본문 템플릿은 업무 문구다. 복사해 쓸 때 통째로 교체한다.
 * @param
 * @returns
 * @hidden N
*/
scwin.getLeadComContent = function () {
	return "안녕하세요. 한국거래소 기술기업상장부입니다.\n\n"
		+ "신청하신 전문평가 관련 내용이 업데이트되었으니 제출시스템을 통해 확인하시기 바랍니다.\n"
		+ "(전문평가기관 배정된 경우, 당해 기관에 전문평가 신청시 꼭 제출시스템을 통해 신청일을 입력해주시기\n"
		+ "바랍니다. 필요시 미리 수정요청해주시기 바랍니다.)\n\n"
		+ "감사합니다.";
};

/**
 * @method
 * @name scwin.getReplyRequestContent
 * @author Inswave
 * @date 2026. 08. 18
 * @description 국책기관·TCB 대상 회신요청 발신내용을 반환한다.
 * 국책기관에만 배정순번 안내 문구가 추가된다.
 * @param
 * @returns
 * @hidden N
*/
scwin.getReplyRequestContent = function (comNm, isNatlInst) {
	const common = "안녕하세요. 한국거래소 기술기업상장부(02-3774-9773)입니다.\n\n"
		+ "전문평가대상기업(" + comNm + ")의 평가대상핵심기술/사업(첨부 참조)에 대해\n"
		+ "이해관계여부(평가이력 등을 미기재하여 신청하는 경우가 있어서 확인 요망),\n"
		+ "일정 등을 고려하여 전문평가 가능여부를 X/XX(X)까지 회신 부탁드립니다.\n\n"
		+ "- 평가가 불가능한 경우에도 \"불가능\"으로 메일 회신을 부탁드리며,\n";

	const natlInstOnly = "다수 기관이 평가의사를 밝힐 경우에는 거래소내 배정순번에 따라 평가기관이 배정됩니다.\n\n";

	return common + (isNatlInst ? natlInstOnly : "\n") + "오늘도 좋은 하루 되시기 바랍니다. 감사합니다!";
};

/**
 * @method
